/bin/zsh -c "python3 - <<'PY'
import json,itertools
F=json.load(open('inputs/fees.json'))
def val(field_applies, x):
 return field_applies is None or field_applies==[] or field_applies==x or (isinstance(field_applies,list) and x in field_applies)

def calc(label, pred):
 rows=[f for f in F if pred(f)]
 fees=[f['fixed_amount']+f['rate']*10/10000 for f in rows]
 print(label,len(rows),sum(fees)/len(fees) if fees else None, 'range', (min(fees),max(fees)) if fees else None)
print('Q1273')
calc('GC credit exact True',lambda f:f['card_scheme']=='GlobalCard' and f['is_credit'] is True)
calc('GC credit True/null',lambda f:f['card_scheme']=='GlobalCard' and f['is_credit'] in (True,None))
calc('GC credit True/empty?',lambda f:f['card_scheme']=='GlobalCard' and f['is_credit'] in (True,None,[]))
print('Q1305')
for acct in ('exact','inclempty'):
 for mcc in ('exact','inclempty'):
  def pred(f,acct=acct,mcc=mcc):
   a=f['account_type']==['H'] if acct=='exact' else val(f['account_type'],'H')
   m=f['merchant_category_code']==[5812] if mcc=='exact' else val(f['merchant_category_code'],5812)
   return f['card_scheme']=='GlobalCard' and a and m
  calc(acct+mcc,pred)
print('specific components')
for f in F:
 if f['card_scheme']=='GlobalCard' and 'H' in (f['account_type'] or []) : print(f)
PY"

