F=json.load(open('inputs/fees.json')); M={m['merchant']:m for m in json.load(open('inputs/merchant_data.json'))}
def app(v,x): return v is None or v==[] or v==x or (isinstance(v,list) and x in v)
def delay(x): return x if x in ('immediate','manual','3-5') else ('<3' if x in ('1','2') else '>5')
def fband(p): return '<7.2%' if p<.072 else ('7.2%-7.7%' if p<.077 else ('7.7%-8.3%' if p<=.083 else '>8.3%'))
def vband(v): return '<100k' if v<1e5 else ('100k-1m' if v<1e6 else ('1m-5m' if v<=5e6 else '>5m'))
mdays=[calendar.monthrange(2023,m)[1] for m in range(1,13)]; cum=0; dm={}
for i,n in enumerate(mdays,1):
 for d in range(1,n+1): dm[cum+d]=i
 cum+=n
# collect month metrics and target transactions
metrics={mo:[0.,0.] for mo in range(1,13)}; txs=[]
for r in csv.DictReader(open('inputs/payments.csv')):
 if r['merchant']"'!='"'Belles_cookbook_store': continue
 mo=dm[int(r['day_of_year'])]; a=float(r['eur_amount']); metrics[mo][0]+=a; metrics[mo][1]+=a if r['has_fraudulent_dispute']=='True' else 0
 txs.append((mo,r))
P=M['Belles_cookbook_store']; pd=delay(P['capture_delay'])
for label, cond in [('day10 Jan',lambda mo,r:mo==1 and int(r['day_of_year'])==10),('Jan',lambda mo,r:mo==1),('Mar',lambda mo,r:mo==3)]:
 for strict in (False,True):
  ids=set(); per=collections.Counter()
  for mo,r in txs:
   if not cond(mo,r): continue
   dom=r['issuing_country']==r['acquirer_country']; vb=vband(metrics[mo][0]); fbn=fband(metrics[mo][1]/metrics[mo][0])
   for f in F:
    if f['card_scheme']"'!=r['"'card_scheme']: continue
    if not app(f['account_type'],P['account_type']): continue
    if not (f['capture_delay'] is None or f['capture_delay']==pd): continue
    if not (f['monthly_fraud_level'] is None or f['monthly_fraud_level']==fbn): continue
    if not (f['monthly_volume'] is None or f['monthly_volume']==vb): continue
    if not app(f['merchant_category_code'],P['merchant_category_code']): continue
    if strict: ok=(f['is_credit'] is r['is_credit']=='True')
    else: ok=(f['is_credit'] is None or f['is_credit']==(r['is_credit']=='True'))
    if not ok: continue
    if not app(f['aci'],r['aci']): continue
    if not (f['intracountry'] is None or bool(f['intracountry'])==dom): continue
    ids.add(f['ID']); per[f['ID']]+=1
  print(label,'strict' if strict else 'wild',len(ids),sorted(ids))
