import csv, json, calendar
from collections import defaultdict
from decimal import Decimal, ROUND_HALF_UP

with open('inputs/fees.json', encoding='utf-8') as fh:
    fees = json.load(fh)
with open('inputs/merchant_data.json', encoding='utf-8') as fh:
    merchants = {m['merchant']: m for m in json.load(fh)}

def applies(value, target):
    return value is None or value == [] or value == target or (isinstance(value, list) and target in value)

def delay_band(value):
    if value in ('immediate', 'manual', '3-5'):
        return value
    if value in ('1', '2'):
        return '<3'
    if value == '7':
        return '>5'
    raise ValueError(value)

def fraud_band(rate):
    pct = rate * 100
    if pct < 7.2:
        return '<7.2%'
    if pct < 7.7:
        return '7.2%-7.7%'
    if pct <= 8.3:
        return '7.7%-8.3%'
    return '>8.3%'

def volume_band(volume):
    if volume < 100000:
        return '<100k'
    if volume < 1000000:
        return '100k-1m'
    if volume <= 5000000:
        return '1m-5m'
    return '>5m'

def q6(value, places):
    return format(value.quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP), f'.{places}f')

# Calendar-month lookup for 2023.
month_days = [calendar.monthrange(2023, m)[1] for m in range(1, 13)]
day_to_month = {}
acc = 0
for month, days in enumerate(month_days, 1):
    for day in range(1, days + 1):
        day_to_month[acc + day] = month
    acc += days

issuing_counts = defaultdict(int)
fraud_ip_counts = defaultdict(int)
martinis_month = defaultdict(lambda: [Decimal(0), Decimal(0)])
belles_month = defaultdict(lambda: [Decimal(0), Decimal(0)])
belles_transactions = []

with open('inputs/payments.csv', newline='', encoding='utf-8') as fh:
    for row in csv.DictReader(fh):
        merchant = row['merchant']
        amount = Decimal(row['eur_amount'])
        fraud = row['has_fraudulent_dispute'] == 'True'
        issuing_counts[row['issuing_country']] += 1
        if fraud:
            fraud_ip_counts[row['ip_country']] += 1
        month = day_to_month[int(row['day_of_year'])]
        if merchant == 'Martinis_Fine_Steakhouse':
            martinis_month[month][0] += amount
            if fraud:
                martinis_month[month][1] += amount
        if merchant == 'Belles_cookbook_store':
            belles_month[month][0] += amount
            if fraud:
                belles_month[month][1] += amount
            belles_transactions.append((month, row, amount, fraud))

# Q1273 and Q1305: average fee for a 10 EUR transaction over all applicable rules.
def avg_fee(rows):
    values = [Decimal(str(f['fixed_amount'])) + Decimal(f['rate']) * Decimal(10) / Decimal(10000) for f in rows]
    return q6(sum(values) / Decimal(len(values)), 6)

q1273_rows = [f for f in fees if f['card_scheme'] == 'GlobalCard' and applies(f['is_credit'], True)]
q1305_rows = [f for f in fees if f['card_scheme'] == 'GlobalCard' and applies(f['account_type'], 'H') and applies(f['merchant_category_code'], 5812)]
q1273 = avg_fee(q1273_rows)
q1305 = avg_fee(q1305_rows)

# Q1464: rules whose constraints permit R and B; empty/null constraints permit all values.
q1464_ids = sorted(f['ID'] for f in fees if applies(f['account_type'], 'R') and applies(f['aci'], 'B'))

# Q1681/Q1753: union of rules matching any transaction in the requested period.
def belles_ids(month, day_of_year=None):
    merchant = merchants['Belles_cookbook_store']
    merchant_delay = delay_band(merchant['capture_delay'])
    result = set()
    volume, fraud_volume = belles_month[month]
    level = fraud_band(fraud_volume / volume)
    vol_band = volume_band(volume)
    for tx_month, row, amount, fraud in belles_transactions:
        if tx_month "'!= month or (day_of_year is not None and int(row['"'day_of_year']) "'!= day_of_year):
            continue
        domestic = row['"'issuing_country'] == row['acquirer_country']
        is_credit = row['is_credit'] == 'True'
        for f in fees:
            if f['card_scheme'] "'!= row['"'card_scheme']:
                continue
            if not applies(f['account_type'], merchant['account_type']):
                continue
            if f['capture_delay'] is not None and f['capture_delay'] "'!= merchant_delay:
                continue
            if f['"'monthly_fraud_level'] is not None and f['monthly_fraud_level'] "'!= level:
                continue
            if f['"'monthly_volume'] is not None and f['monthly_volume'] "'!= vol_band:
                continue
            if not applies(f['"'merchant_category_code'], merchant['merchant_category_code']):
                continue
            if f['is_credit'] is not None and f['is_credit'] "'!= is_credit:
                continue
            if not applies(f['"'aci'], row['aci']):
                continue
            if f['intracountry'] is not None and bool(f['intracountry']) "'!= domestic:
                continue
            result.add(f['"'ID'])
    return sorted(result)

q1681_ids = belles_ids(1, 10)
q1753_ids = belles_ids(3)

# Q1871: change rule 384's rate from 14 to 1 for all January transactions it applies to.
fee_384 = next(f for f in fees if f['ID'] == 384)
rule_384_amount = sum(
    amount for month, row, amount, fraud in belles_transactions
    if month == 1 and row['card_scheme'] == fee_384['card_scheme'] and applies(fee_384['aci'], row['aci'])
    and (fee_384['is_credit'] is None or fee_384['is_credit'] == (row['is_credit'] == 'True'))
)
delta = (Decimal(1) - Decimal(fee_384['rate'])) * rule_384_amount / Decimal(10000)
q1871 = q6(delta, 14)

# Q2697: for each alternative ACI, take the cheapest applicable rule per fraudulent January transaction.
belles = merchants['Belles_cookbook_store']
belles_delay = delay_band(belles['capture_delay'])
jan_volume, jan_fraud_volume = belles_month[1]
jan_level = fraud_band(jan_fraud_volume / jan_volume)
jan_vol_band = volume_band(jan_volume)
base_fee_rules = []
for f in fees:
    if not applies(f['account_type'], belles['account_type']):
        continue
    if f['capture_delay'] is not None and f['capture_delay'] "'!= belles_delay:
        continue
    if f['"'monthly_fraud_level'] is not None and f['monthly_fraud_level'] "'!= jan_level:
        continue
    if f['"'monthly_volume'] is not None and f['monthly_volume'] "'!= jan_vol_band:
        continue
    if not applies(f['"'merchant_category_code'], belles['merchant_category_code']):
        continue
    if f['is_credit'] is not None and f['is_credit'] is not True:
        continue
    if f['intracountry'] is not None and bool(f['intracountry']) is not False:
        continue
    base_fee_rules.append(f)

fraud_transactions = [(row, amount) for month, row, amount, fraud in belles_transactions if month == 1 and fraud]
aci_costs = {}
for aci in 'ABCDEFG':
    total = Decimal(0)
    covered = 0
    for row, amount in fraud_transactions:
        candidates = [f for f in base_fee_rules if f['card_scheme'] == row['card_scheme'] and applies(f['aci'], aci)]
        if not candidates:
            continue
        covered += 1
        per_tx = [Decimal(str(f['fixed_amount'])) + Decimal(f['rate']) * amount / Decimal(10000) for f in candidates]
        total += min(per_tx)
    aci_costs[aci] = (covered, total)
# Only ACIs that can cover every fraudulent transaction are viable global choices.
viable = [(aci, data[1]) for aci, data in aci_costs.items() if data[0] == len(fraud_transactions)]
best_aci, best_cost = min(viable, key=lambda item: (item[1], item[0]))
q2697 = f'{best_aci}:{q6(best_cost, 2)}'

answers = [
    ('5', max(issuing_counts.items(), key=lambda item: item[1])[0]),
    ('49', 'A. NL'),
    ('70', 'yes'),
    ('1273', q1273),
    ('1305', q1305),
    ('1464', ', '.join(map(str, q1464_ids))),
    ('1681', ', '.join(map(str, q1681_ids))),
    ('1753', ', '.join(map(str, q1753_ids))),
    ('1871', q1871),
    ('2697', q2697),
]

with open('answers.jsonl', 'w', encoding='utf-8') as fh:
    for task_id, answer in answers:
        fh.write(json.dumps({'task_id': task_id, 'answer': answer}, ensure_ascii=False) + '\\n')

print('counts:', issuing_counts.most_common(3))
print('fraud IP counts:', fraud_ip_counts.most_common(4))
print('avg-rule counts:', len(q1273_rows), len(q1305_rows))
print('id-list counts:', len(q1464_ids), len(q1681_ids), len(q1753_ids))
print('1871 amount/delta:', rule_384_amount, q1871)
print('ACI options:', {k:(v[0], str(v[1])) for k,v in aci_costs.items()})
print('Q2697:', q2697)
PY"

